mapper.select:
SELECT IFNULL(sum(`record_num`),0)
FROM `passenger_flow_record`


        and `in_out` = #{way}


        and `record_time` BETWEEN #{startTime} and #{endTime}

SELECT `area_name` `areaName`,IFNULL(sum(`record_num`),0) `num` FROM `passenger_flow_record` where
`record_time` >= #{param.period.begin}
and `record_time` <= #{param.period.end}
GROUP BY `area_name` order by `num` DESC
limit 10

SELECT IFNULL(sum(`record_num`),0) `num`,DATE_FORMAT(`record_time`,${timeFlag}) `timeFlag`
FROM `passenger_flow_record`


        `record_time` >= #{st}


        and `record_time` <= #{et}


GROUP BY DATE_FORMAT(`record_time`,${timeFlag})
